146	        rejectBlankOwnerFields(ownerFieldsDto);
147	        rejectInvalidPostcode(ownerFieldsDto);
148	        normalizeTelephone(ownerFieldsDto);
149	        normalizeEmail(ownerFieldsDto);
150	        String householdId = householdIdFor(ownerFieldsDto);
151	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
152	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
153	        rejectHouseholdDuplicate(householdId, sharesHousehold);
154	        rejectCityAtCapacity(ownerFieldsDto.getCity());
155	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
156	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
157	        long registeredThatDay = countRegisteredOn(registrationDate);
158	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
159	        HttpHeaders headers = new HttpHeaders();
160	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
161	        owner.setRegistrationDate(registrationDate);
162	        owner.setHouseholdId(householdId);
163	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
164	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
165	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
166	        markPossibleDuplicate(owner, sharesHousehold);
167	        this.clinicService.saveOwner(owner);
168	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
