271	
272	    /**
273	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
274	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
275	     * the request body already rejects null and empty values, but permits whitespace-only strings
276	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
277	     * that gap so every required field must carry a non-blank value.
278	     *
279	     * @param ownerFieldsDto the submitted owner fields
280	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
281	     */
282	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
283	        List<String> missing = new ArrayList<>();
284	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
285	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
286	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
287	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
288	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
289	        if (!missing.isEmpty()) {
290	            throw new InvalidOwnerFieldsException(missing);
291	        }
292	    }
293	
294	    /**
295	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
296	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
297	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
298	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
299	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
300	     * {@link PostcodeValidator}.
301	     *
302	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
303	     *                       {@link #rejectBlankOwnerFields} having already run)
304	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
305	     */
306	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
307	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
308	            throw new InvalidOwnerFieldsException(List.of("postcode"));
309	        }
310	    }
311	
312	    private void addIfBlank(List<String> missing, String fieldName, String value) {
313	        if (value == null || value.isBlank()) {
314	            missing.add(fieldName);
315	        }
316	    }
317	
318	    /**
319	     * Normalizes the submitted {@code address} on create to its canonical form (see
320	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
321	     * stored and returned, and the form every later address comparison (the required-field check,
322	     * household duplicate detection and the shared household id) is judged on. A null address is left
323	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
324	     * after normalization likewise reduces to the empty string and is rejected there.
325	     *
326	     * @param ownerFieldsDto the submitted owner fields
327	     */
328	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
329	        String address = ownerFieldsDto.getAddress();
330	        if (address == null) {
331	            return;
332	        }
333	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
334	    }
335	
336	    /**
337	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
338	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
339	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
340	     * {@code 400 Bad Request}.
341	     *
342	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
343	     *                       {@link #rejectBlankOwnerFields} having already run)
344	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
345	     */
346	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
347	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
348	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
349	        ownerFieldsDto.setTelephone(normalized);
350	    }
351	
352	    /**
353	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
354	     * untouched (email is optional). When present it is reduced to its canonical form (see
355	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
356	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
357	     *
358	     * @param ownerFieldsDto the submitted owner fields
359	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
360	     */
361	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
362	        String email = ownerFieldsDto.getEmail();
363	        if (email == null || email.isBlank()) {
364	            return;
365	        }
366	        String normalized = EmailNormalizer.normalize(email)
367	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
368	        ownerFieldsDto.setEmail(normalized);
369	    }
370	
371	    /**
372	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
373	     * duplicate detection is now expressed through the single derived {@code identityKey}
374	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
375	     * which replaces the previously separate telephone, email and household checks. Two owners denote
376	     * the same person when their identities collide on the telephone - the identity's distinguishing
377	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
378	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
379	     * same household with different telephones have different identities and are both allowed; an email
380	     * or a household on its own no longer makes a duplicate.
381	     *
382	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
383	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
384	     * @param householdId    the household id derived for the owner being created (see
385	     *                       {@link HouseholdNormalizer#toHouseholdId})
386	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
387	     */
388	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
389	        String identityKey = OwnerIdentity.identityKey(
390	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
391	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
392	        boolean inUse = this.clinicService.findAllOwners().stream()
393	            .map(Owner::getTelephone)
394	            .filter(Objects::nonNull)
395	            .map(TelephoneNormalizer::toComparisonKey)
396	            .anyMatch(telephoneKey::equals);
397	        if (inUse) {
398	            throw new DuplicateOwnerIdentityException(identityKey);
399	        }
400	    }
401	
402	    /**
403	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
404	     * both match the submitted values, compared case-insensitively. The count reflects only owners
405	     * already persisted at the time of the create, so the owner being created is never included.
406	     *
407	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
408	     *                  having already run)
409	     * @param lastName  the submitted last name (non-blank here)
410	     * @return the number of existing owners sharing the same first and last name
411	     */
412	    private int countNamesakes(String firstName, String lastName) {
413	        return (int) this.clinicService.findAllOwners().stream()
414	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
415	                && lastName.equalsIgnoreCase(owner.getLastName()))
416	            .count();
417	    }
418	
419	    /**
420	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
421	     * whose stored {@code householdId} equals the value derived for the owner being created. The
422	     * count reflects only owners already persisted at the time of the create, so the owner being
423	     * created is never included; callers add one to obtain the household size after this create.
424	     *
425	     * @param householdId the household identifier derived for the owner being created (see
426	     *                    {@link HouseholdNormalizer#toHouseholdId})
427	     * @return the number of existing owners already sharing that household
428	     */
429	    private int countHouseholdMembers(String householdId) {
430	        if (householdId == null) {
431	            return 0;
432	        }
433	        return (int) this.clinicService.findAllOwners().stream()
434	            .map(Owner::getHouseholdId)
435	            .filter(householdId::equals)
436	            .count();
437	    }
438	
439	    /**
440	     * Derives the household id an owner should carry from its submitted fields (see
441	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
442	     * household id, so routing them through this single method keeps them agreed on which of the
443	     * owner's fields key the household.
444	     *
445	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
446	     *                       {@link #rejectBlankOwnerFields} having already run on create)
447	     * @return the owner's household id
448	     */
449	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
450	        return HouseholdNormalizer.toHouseholdId(
451	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
452	    }
453	
454	    /**
455	     * Rejects creating an owner that would join an existing household without declaring itself a
456	     * member. The household is keyed on (last name, postcode) through the derived {@code householdId}
457	     * (see {@link HouseholdNormalizer#toHouseholdId}), so a second owner sharing an existing owner's
458	     * last name and postcode denotes the same household. Such a create is reported as a {@code 409
459	     * Conflict} unless it opts in with {@code sharesHousehold}, in which case it is accepted as a
460	     * declared household member. Only owners already persisted (before this create) are considered.
461	     *
462	     * @param householdId     the household id derived for the owner being created
463	     * @param sharesHousehold whether the request opted in to sharing a household
464	     * @throws DuplicateOwnerHouseholdException if the household already exists and the request did not
465	     *                                          opt in with {@code sharesHousehold}
466	     */
467	    private void rejectHouseholdDuplicate(String householdId, boolean sharesHousehold) {
468	        if (sharesHousehold || householdId == null) {
469	            return;
470	        }
471	        boolean householdExists = this.clinicService.findAllOwners().stream()
472	            .map(Owner::getHouseholdId)
473	            .anyMatch(householdId::equals);
474	        if (householdExists) {
475	            throw new DuplicateOwnerHouseholdException(householdId);
476	        }
477	    }
478	
479	    /**
480	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
481	     * is none. The create has already cleared the hard-duplicate identity check
482	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
483	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
484	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
485	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
486	     * original record; owners with no postcode never match, since a shared postcode is required.
487	     *
488	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
489	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
490	     *         duplicate
491	     */
492	    private Integer findPossibleDuplicate(Owner owner) {
493	        String postcode = owner.getPostcode();
494	        if (postcode == null) {
495	            return null;
496	        }
497	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
498	        return this.clinicService.findAllOwners().stream()
499	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
500	            .filter(existing -> postcode.equals(existing.getPostcode()))
501	            .filter(existing -> existing.getTelephone() != null
502	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
503	            .map(Owner::getId)
504	            .filter(Objects::nonNull)
505	            .min(Integer::compareTo)
506	            .orElse(null);
507	    }
508	
509	    /**
510	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
511	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
512	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
513	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
514	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
515	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
516	     * duplicate, so it is never flagged.
517	     *
518	     * @param owner           the owner being created, with telephone already normalized and
519	     *                        lastName/postcode set
520	     * @param sharesHousehold whether the request opted in to sharing a household
521	     */
522	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
523	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
524	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
525	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
526	    }
527	
528	    /**
529	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
530	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
531	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
532	     *
533	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
534	     *             run)
535	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
536	     */
537	    private void rejectCityAtCapacity(String city) {
538	        long ownersInCity = this.clinicService.findAllOwners().stream()
539	            .map(Owner::getCity)
540	            .filter(Objects::nonNull)
541	            .filter(city::equalsIgnoreCase)
542	            .count();
543	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
544	            throw new OwnerCityAtCapacityException(city);
545	        }
546	    }
547	
548	    /**
549	     * Resolves the effective registration date for a create, rolled onto a business day. The
550	     * supplied date is used when present, otherwise the server's current date; either way the result
551	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
552	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
553	     * stored {@code registrationDate}, the membership number's year segment and the daily
554	     * create-limit's per-day count - is judged on this adjusted date.
555	     *
556	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
557	     *                                 default to the server's current date
558	     * @return the effective registration date, guaranteed to fall on a business day
559	     */
560	    /**
561	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
562	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
563	     * adjustment; a future date cannot describe a registration that has already happened, so it is
564	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
565	     * server's current date) and any date on or before today are accepted.
566	     *
567	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
568	     *                                 omitted
569	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
570	     */
571	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
572	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
573	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
574	        }
575	    }
576	
577	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
578	        LocalDate registrationDate =
579	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
580	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
581	    }
582	
583	    /**
584	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
585	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
586	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
587	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
588	     * Too Many Requests}.
589	     *
590	     * @param registrationDate   the create's effective registration date, already rolled onto a
591	     *                           business day by {@link #effectiveRegistrationDate}
592	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
593	     *                           {@code registrationDate} equals {@code registrationDate}
594	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
595	     *                                              owner registrations
596	     */
597	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
598	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
599	            throw new OwnerDailyRegistrationLimitException(registrationDate);
600	        }
601	    }
602	
603	    /**
604	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
605	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
606	     * bulk-signup warning are judged on.
607	     *
608	     * @param registrationDate the create's effective registration date, already rolled onto a business
609	     *                         day by {@link #effectiveRegistrationDate}
610	     * @return the number of existing owners registered on that day
611	     */
612	    private long countRegisteredOn(LocalDate registrationDate) {
613	        return this.clinicService.findAllOwners().stream()
614	            .map(Owner::getRegistrationDate)
615	            .filter(registrationDate::equals)
616	            .count();
617	    }
618	}
